   1: // JSON Pointer (RFC 6901) and JSON Patch (RFC 6902).
   2: 
   3: export class PatchError extends Error {
   4:   constructor(message, index) {
   5:     super(message);
   6:     this.name = 'PatchError';
   7:     this.index = index;
   8:   }
   9: }
  10: 
  11: const OPS = ['add', 'remove', 'replace', 'move', 'copy', 'test'];
  12: const INDEX_RE = /^(?:0|[1-9][0-9]*)$/;
  13: 
  14: function isValidPointer(pointer) {
  15:   if (pointer === '') return true;
  16:   if (pointer[0] !== '/') return false;
  17:   return !/~(?![01])/.test(pointer);
  18: }
  19: 
  20: function decodeTokens(pointer) {
  21:   if (pointer === '') return [];
  22:   return pointer
  23:     .slice(1)
  24:     .split('/')
  25:     .map((t) => t.replace(/~[01]/g, (m) => (m === '~1' ? '/' : '~')));
  26: }
  27: 
  28: export function parsePointer(pointer) {
  29:   if (typeof pointer !== 'string') throw new TypeError('pointer must be a string');
  30:   if (!isValidPointer(pointer)) throw new SyntaxError('invalid pointer');
  31:   return decodeTokens(pointer);
  32: }
  33: 
  34: function isContainer(v) {
  35:   return typeof v === 'object' && v !== null;
  36: }
  37: 
  38: function defineMember(obj, key, value) {
  39:   Object.defineProperty(obj, key, {
  40:     value,
  41:     writable: true,
  42:     enumerable: true,
  43:     configurable: true,
  44:   });
  45: }
  46: 
  47: // Iterative deep copy of a JSON value; keeps member order and -0.
  48: function deepCopy(value) {
  49:   if (!isContainer(value)) return value;
  50:   const root = Array.isArray(value) ? [] : {};
  51:   const stack = [[value, root]];
  52:   while (stack.length > 0) {
  53:     const [src, dst] = stack.pop();
  54:     if (Array.isArray(src)) {
  55:       for (let i = 0; i < src.length; i++) {
  56:         const v = src[i];
  57:         if (isContainer(v)) {
  58:           const c = Array.isArray(v) ? [] : {};
  59:           dst.push(c);
  60:           stack.push([v, c]);
  61:         } else {
  62:           dst.push(v);
  63:         }
  64:       }
  65:     } else {
  66:       for (const k of Object.keys(src)) {
  67:         const v = src[k];
  68:         if (isContainer(v)) {
  69:           const c = Array.isArray(v) ? [] : {};
  70:           defineMember(dst, k, c);
  71:           stack.push([v, c]);
  72:         } else {
  73:           defineMember(dst, k, v);
  74:         }
  75:       }
  76:     }
  77:   }
  78:   return root;
  79: }
  80: 
  81: // Iterative JSON equality.
  82: function jsonEqual(a, b) {
  83:   const stack = [[a, b]];
  84:   while (stack.length > 0) {
  85:     const [x, y] = stack.pop();
  86:     if (!isContainer(x) || !isContainer(y)) {
  87:       if (x !== y) return false;
  88:       continue;
  89:     }
  90:     const xa = Array.isArray(x);
  91:     if (xa !== Array.isArray(y)) return false;
  92:     if (xa) {
  93:       if (x.length !== y.length) return false;
  94:       for (let i = 0; i < x.length; i++) stack.push([x[i], y[i]]);
  95:     } else {
  96:       const kx = Object.keys(x);
  97:       if (kx.length !== Object.keys(y).length) return false;
  98:       for (const k of kx) {
  99:         if (!Object.hasOwn(y, k)) return false;
 100:         stack.push([x[k], y[k]]);
 101:       }
 102:     }
 103:   }
 104:   return true;
