 107: // Returns the child named by token, or throws with the right reason.
 108: function step(node, token, notFound, fail) {
 109:   if (Array.isArray(node)) {
 110:     if (token === '-') fail(notFound);
 111:     if (!INDEX_RE.test(token)) fail('bad index');
 112:     const i = Number(token);
 113:     if (i >= node.length) fail(notFound);
 114:     return node[i];
 115:   }
 116:   if (isContainer(node)) {
 117:     if (!Object.hasOwn(node, token)) fail(notFound);
 118:     return node[token];
 119:   }
 120:   return fail(notFound);
 121: }
