 123: function resolve(doc, tokens, notFound, fail) {
 124:   let node = doc;
 125:   for (const t of tokens) node = step(node, t, notFound, fail);
 126:   return node;
 127: }
 128: 
 129: function resolveParent(doc, tokens, notFound, fail) {
 130:   return resolve(doc, tokens.slice(0, -1), notFound, fail);
 131: }
