 133: function addAt(doc, tokens, value, fail) {
 134:   if (tokens.length === 0) return value;
 135:   const parent = resolveParent(doc, tokens, 'path not found', fail);
 136:   const last = tokens[tokens.length - 1];
 137:   if (Array.isArray(parent)) {
 138:     if (last === '-') {
 139:       parent.push(value);
 140:     } else {
 141:       if (!INDEX_RE.test(last)) fail('bad index');
 142:       const i = Number(last);
 143:       if (i > parent.length) fail('path not found');
 144:       parent.splice(i, 0, value);
 145:     }
 146:   } else if (isContainer(parent)) {
 147:     defineMember(parent, last, value);
 148:   } else {
 149:     fail('path not found');
 150:   }
 151:   return doc;
 152: }
 153: 
 154: function removeAt(doc, tokens, notFound, fail) {
 155:   const parent = resolveParent(doc, tokens, notFound, fail);
 156:   const last = tokens[tokens.length - 1];
 157:   step(parent, last, notFound, fail);
 158:   if (Array.isArray(parent)) parent.splice(Number(last), 1);
 159:   else delete parent[last];
 160: }
 161: 
 162: function isProperPrefix(a, b) {
 163:   if (a.length >= b.length) return false;
 164:   for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
 165:   return true;
 166: }
 167: 
 168: function sameTokens(a, b) {
 169:   return a.length === b.length && a.every((t, i) => t === b[i]);
 170: }
 171: 
 172: function checkOperation(op) {
 173:   if (typeof op !== 'object' || op === null || Array.isArray(op)) return 'not an object';
 174:   if (!Object.hasOwn(op, 'op') || !OPS.includes(op.op)) return 'bad op';
 175:   const name = op.op;
 176:   if (!Object.hasOwn(op, 'path') || typeof op.path !== 'string' || !isValidPointer(op.path)) {
 177:     return 'bad path';
 178:   }
 179:   const path = decodeTokens(op.path);
 180:   let from;
 181:   if (name === 'move' || name === 'copy') {
 182:     if (!Object.hasOwn(op, 'from') || typeof op.from !== 'string' || !isValidPointer(op.from)) {
 183:       return 'bad from';
 184:     }
 185:     from = decodeTokens(op.from);
 186:   }
 187:   if ((name === 'add' || name === 'replace' || name === 'test') && !Object.hasOwn(op, 'value')) {
 188:     return 'missing value';
 189:   }
 190:   if (name === 'remove' && path.length === 0) return 'cannot remove root';
 191:   if (name === 'move' && isProperPrefix(from, path)) return 'cannot move into own child';
 192:   return { op: name, path, from, value: op.value };
 193: }
 194: 
 195: export function applyPatch(doc, patch) {
 196:   if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
 197:   const ops = [];
 198:   for (let i = 0; i < patch.length; i++) {
 199:     const r = checkOperation(patch[i]);
 200:     if (typeof r === 'string') throw new PatchError(`operation ${i}: ${r}`, i);
 201:     ops.push(r);
 202:   }
 203:   let result = deepCopy(doc);
 204:   for (let i = 0; i < ops.length; i++) {
 205:     const fail = (reason) => {
 206:       throw new PatchError(`operation ${i}: ${reason}`, i);
 207:     };
 208:     const { op, path, from, value } = ops[i];
 209:     switch (op) {
 210:       case 'add':
 211:         result = addAt(result, path, deepCopy(value), fail);
 212:         break;
 213:       case 'remove':
 214:         removeAt(result, path, 'path not found', fail);
 215:         break;
 216:       case 'replace': {
 217:         if (path.length === 0) {
 218:           result = deepCopy(value);
 219:           break;
 220:         }
 221:         const parent = resolveParent(result, path, 'path not found', fail);
 222:         const last = path[path.length - 1];
 223:         step(parent, last, 'path not found', fail);
 224:         if (Array.isArray(parent)) parent[Number(last)] = deepCopy(value);
 225:         else defineMember(parent, last, deepCopy(value));
 226:         break;
 227:       }
 228:       case 'move': {
 229:         const v = resolve(result, from, 'from not found', fail);
 230:         // A from of "" is either equal to path or rejected by the form rules.
 231:         if (sameTokens(from, path)) break;
 232:         removeAt(result, from, 'from not found', fail);
 233:         result = addAt(result, path, v, fail);
 234:         break;
 235:       }
 236:       case 'copy': {
 237:         const v = deepCopy(resolve(result, from, 'from not found', fail));
 238:         result = addAt(result, path, v, fail);
 239:         break;
 240:       }
 241:       case 'test': {
 242:         const v = resolve(result, path, 'path not found', fail);
 243:         if (!jsonEqual(v, value)) fail('test failed');
