202: export function applyPatch(doc, patch) {
203:   if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
204:   const ops = [];
205:   for (let i = 0; i < patch.length; i++) {
206:     const form = checkForm(patch[i]);
207:     if (typeof form === 'string') throw new PatchError(`operation ${i}: ${form}`, i);
208:     ops.push(form);
209:   }
210:   let result = deepCopy(doc);
211:   for (let i = 0; i < ops.length; i++) {
212:     try {
213:       result = applyOne(result, ops[i]);
214:     } catch (err) {
215:       if (err instanceof StepError) throw new PatchError(`operation ${i}: ${err.message}`, i);
216:       throw err;
217:     }
218:   }
219:   return result;
220: }
  1: #!/usr/bin/env node
  2: // Usage: node jsonpatch-cli.mjs <patch> [<doc>]
  3: import { once } from 'node:events';
  4: import { fstatSync } from 'node:fs';
  5: import { open, stat } from 'node:fs/promises';
  6: import { applyPatch, PatchError } from './jsonpatch.mjs';
  7: 
  8: const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
  9: const MAX_BYTES = 1048576;
 10: const MAX_DEPTH = 1000;
 11: const CHUNK = 65536;
 12: const OUTPUT_CHUNK = 1 << 20;
 13: 
 14: class CliError extends Error {
 15:   constructor(message, code) {
 16:     super(message);
 17:     this.code = code;
 18:   }
 19: }
 20: 
 21: const readFailure = (name, reason) => new CliError(`Error: ${name}: ${reason}`, 1);
 22: 
 23: async function isDirectory(path) {
 24:   try {
 25:     return (await stat(path)).isDirectory();
 26:   } catch {
 27:     return false;
 28:   }
 29: }
 30: 
 31: async function readFileInput(path) {
 32:   let handle;
 33:   try {
 34:     handle = await open(path, 'r');
 35:   } catch (err) {
 36:     if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw readFailure(path, 'no such file');
 37:     if (err.code === 'EISDIR' || (await isDirectory(path))) throw readFailure(path, 'is a directory');
 38:     throw readFailure(path, 'cannot read');
 39:   }
 40:   try {
 41:     if ((await handle.stat()).isDirectory()) throw readFailure(path, 'is a directory');
 42:     const chunks = [];
 43:     let total = 0;
 44:     for (;;) {
 45:       const buf = Buffer.alloc(CHUNK);
 46:       const { bytesRead } = await handle.read(buf, 0, CHUNK, null);
 47:       if (bytesRead === 0) break;
 48:       total += bytesRead;
 49:       if (total > MAX_BYTES) throw readFailure(path, 'too large');
 50:       chunks.push(buf.subarray(0, bytesRead));
 51:     }
 52:     return Buffer.concat(chunks);
 53:   } catch (err) {
 54:     if (err instanceof CliError) throw err;
 55:     if (err.code === 'EISDIR') throw readFailure(path, 'is a directory');
 56:     throw readFailure(path, 'cannot read');
 57:   } finally {
 58:     await handle.close().catch(() => {});
 59:   }
 60: }
 61: 
 62: // A stream on a directory ends silently with no data, so fd 0 is checked first.
 63: function stdinIsReadable() {
 64:   try {
 65:     return !fstatSync(0).isDirectory();
 66:   } catch {
 67:     return false;
 68:   }
 69: }
 70: 
 71: function readStdin() {
 72:   if (!stdinIsReadable()) return Promise.reject(readFailure('stdin', 'cannot read'));
 73:   return new Promise((resolve, reject) => {
 74:     const stdin = process.stdin;
 75:     const chunks = [];
 76:     let total = 0;
 77:     const finish = (err) => {
 78:       stdin.removeAllListeners('data');
 79:       stdin.removeAllListeners('end');
 80:       stdin.destroy();
 81:       if (err) reject(err);
 82:       else resolve(Buffer.concat(chunks));
 83:     };
 84:     stdin.on('data', (chunk) => {
 85:       total += chunk.length;
 86:       if (total > MAX_BYTES) finish(readFailure('stdin', 'too large'));
 87:       else chunks.push(chunk);
 88:     });
 89:     stdin.on('end', () => finish(null));
 90:     stdin.on('error', () => finish(readFailure('stdin', 'cannot read')));
 91:   });
 92: }
 93: 
 94: function jsonDepth(value) {
 95:   let max = 0;
 96:   const stack = [[value, 0]];
 97:   while (stack.length > 0) {
 98:     const [v, depth] = stack.pop();
 99:     if (v === null || typeof v !== 'object') {
100:       max = Math.max(max, depth);
101:       continue;
102:     }
103:     max = Math.max(max, depth + 1);
104:     for (const child of Array.isArray(v) ? v : Object.values(v)) stack.push([child, depth + 1]);
105:   }
106:   return max;
107: }
108: 
109: // Yields JSON.stringify(value, null, 2) in chunks, iteratively: a patch can
110: // build a result far deeper and larger than the native one handles.
111: function* prettyChunks(value) {
112:   let out = '';
113:   const push = (text) => {
114:     out += text;
115:   };
116:   const newline = (depth) => `\n${'  '.repeat(depth)}`;
117:   // Each frame is a container being written and the index of its next entry.
118:   const frames = [];
119:   const writeValue = (v, depth) => {
120:     if (v === null || typeof v !== 'object') {
121:       push(JSON.stringify(v));
122:       return;
123:     }
124:     const isArr = Array.isArray(v);
125:     const keys = isArr ? null : Object.keys(v);
126:     const count = isArr ? v.length : keys.length;
127:     if (count === 0) {
128:       push(isArr ? '[]' : '{}');
129:       return;
130:     }
131:     push(isArr ? '[' : '{');
132:     frames.push({ v, isArr, keys, count, depth, next: 0 });
133:   };
134:   writeValue(value, 0);
135:   while (frames.length > 0) {
136:     if (out.length >= OUTPUT_CHUNK) {
137:       yield out;
138:       out = '';
139:     }
140:     const frame = frames[frames.length - 1];
141:     const { v, isArr, keys, count, depth } = frame;
142:     if (frame.next === count) {
143:       frames.pop();
144:       push(`${newline(depth)}${isArr ? ']' : '}'}`);
145:       continue;
146:     }
147:     const i = frame.next++;
148:     push(`${i > 0 ? ',' : ''}${newline(depth + 1)}`);
149:     if (isArr) {
150:       writeValue(v[i], depth + 1);
151:     } else {
152:       push(`${JSON.stringify(keys[i])}: `);
153:       writeValue(v[keys[i]], depth + 1);
154:     }
155:   }
156:   yield out;
157: }
158: 
159: const inputFailure = (name, reason) => new CliError(`Error: ${name}: ${reason}`, 3);
160: 
161: async function loadInput(arg) {
162:   const name = arg === '-' ? 'stdin' : arg;
163:   const bytes = arg === '-' ? await readStdin() : await readFileInput(arg);
164:   let text;
165:   try {
166:     text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
167:   } catch {
168:     throw inputFailure(name, 'invalid UTF-8');
169:   }
170:   let value;
171:   try {
172:     value = JSON.parse(text);
173:   } catch {
174:     throw inputFailure(name, 'invalid JSON');
175:   }
176:   if (jsonDepth(value) > MAX_DEPTH) throw inputFailure(name, 'too deep');
177:   return value;
178: }
179: 
180: async function main(args) {
181:   if (args.length < 1 || args.length > 2) throw new CliError(USAGE, 2);
182:   const [patchArg, docArg = '-'] = args;
183:   if (patchArg === '-' && docArg === '-') throw new CliError(USAGE, 2);
184:   const patch = await loadInput(patchArg);
185:   const doc = await loadInput(docArg);
186:   let result;
187:   try {
188:     result = applyPatch(doc, patch);
189:   } catch (err) {
190:     if (err instanceof PatchError) throw new CliError(`Error: ${err.message}`, 4);
191:     throw err;
192:   }
193:   for (const chunk of prettyChunks(result)) {
194:     if (!process.stdout.write(chunk)) await once(process.stdout, 'drain');
195:   }
196:   process.stdout.write('\n');
197: }
198: 
199: // A closed or failing stdout (for example a reader that quits early, EPIPE)
200: // ends the run with one line instead of an unhandled 'error' event.
201: process.stdout.on('error', () => {
202:   process.stderr.write('Error: stdout: cannot write\n');
203:   process.exit(1);
204: });
205: 
206: try {
207:   await main(process.argv.slice(2));
208: } catch (err) {
209:   // Anything unexpected still ends as one plain line rather than a stack trace.
210:   const cliErr = err instanceof CliError ? err : new CliError(`Error: ${err?.message ?? err}`, 1);
211:   process.stderr.write(`${cliErr.message}\n`);
212:   process.exitCode = cliErr.code;
213: }

